WITH exploded AS (SELECT id, customer_id, created_at, coupon_codes, elem.product_id, elem.qty, elem.promo FROM carts LATERAL VIEW EXPLODE(items) t AS elem) SELECT *, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY qty NULLS LAST) AS qty_cume_dist, MIN(qty) OVER (PARTITION BY promo) AS promo_min_qty, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY qty DESC) AS qty_cume_dist_2, STDDEV_SAMP(qty) OVER (PARTITION BY promo) AS promo_stddev_samp_qty FROM exploded
